{
  "hypotheses": [
    {
      "risk": "The order_ts column in the orders table may contain timestamps that are not in UTC format.",
      "bug_type": "timezone_day_boundary",
      "probe_sql": "SELECT COUNT(*) AS non_utc_orders FROM orders WHERE order_ts NOT LIKE '%Z'",
      "settles": "A count greater than 0 would confirm this issue, while a count of 0 would rule it out."
    },
    {
      "risk": "The order_ts column may contain timestamps that fall outside the expected range for January 2026.",
      "bug_type": "date_range_truncation",
      "probe_sql": "SELECT COUNT(*) AS out_of_range_orders FROM orders WHERE order_ts < '2026-01-01' OR order_ts >= '2026-02-01'",
      "settles": "A count greater than 0 would confirm this issue, while a count of 0 would rule it out."
    },
    {
      "risk": "The orders table may contain orders with a NULL status that are not being counted.",
      "bug_type": "null_swallowing_predicate",
      "probe_sql": "SELECT COUNT(*) AS null_status_orders FROM orders WHERE order_ts >= '2026-01-01' AND order_ts < '2026-02-01' AND status IS NULL",
      "settles": "A count greater than 0 would confirm this issue, while a count of 0 would rule it out."
    },
    {
      "risk": "There may be orders in January 2026 that have been refunded, which could affect the count of valid orders.",
      "bug_type": "other",
      "probe_sql": "SELECT COUNT(DISTINCT o.order_id) AS refunded_orders FROM orders o JOIN refunds r ON o.order_id = r.order_id WHERE o.order_ts >= '2026-01-01' AND o.order_ts < '2026-02-01'",
      "settles": "A count greater than 0 would confirm this issue, while a count of 0 would rule it out."
    }
  ]
}
